// Generated by tools/generate_float_conversion_tests.py from exact fractions; do not edit by hand.
// Built by nvcc and hipcc, runs without a GPU. The conversions are evaluated at compile time and read at run time,
// std::bit_cast being not constexpr on the __half of HIP; the kernels show that they compile for the device.
#include <bit>
#include <cstdint>
#include <cstdio>

#include "aerobus.h"

namespace {
template<bool negative, uint32_t... digits>
using B = aerobus::bigint::val<negative, digits...>;
using QB = aerobus::FractionField<aerobus::bigint>;

int failures = 0;

void check(bool ok, int line) {
    if (!ok) {
        std::printf("FAILED: line %d\n", line);
        ++failures;
    }
}

uint16_t bits(__half x) {
    return std::bit_cast<uint16_t>(x);
}

template<typename V>
void half_is(uint16_t expected, int line) {
    static constexpr __half value = V::template get<__half>();
    check(bits(value) == expected, line);
}

template<typename V>
void half2_is(uint16_t expected, int line) {
    const __half2 value = V::template get<__half2>();
    check(bits(__low2half(value)) == expected && bits(__high2half(value)) == expected, line);
}
}  // namespace

// the coefficients of a polynomial of tools/polynomial.sollya, evaluated on the device
using R = aerobus::polynomial<QB>::val<
    aerobus::from_hex_float_t<"0x1.0bp-7">,
    aerobus::from_hex_float_t<"-0x1.554p-3">,
    aerobus::from_hex_float_t<"0x1p0">>;

__global__ void half_kernel(const __half* x, __half* y) {
    y[0] = R::eval(x[0]);
    y[1] = B<false, 3U>::get<__half>();
}

__global__ void half2_kernel(const __half2* x, __half2* y) {
    y[0] = R::eval(x[0]);
    y[1] = B<false, 3U>::get<__half2>();
}

